(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=w=>(w.en||'').trim().toLowerCase()+'|'+(w.de||'').trim().toLowerCase();
const clone=x=>JSON.parse(JSON.stringify(x));
const BUILTIN=window.VOCAB_DATA||[];
let customTopics=JSON.parse(localStorage.getItem('vf_custom_topics')||'[]');
let learning=JSON.parse(localStorage.getItem('vf_learning')||'[]');
let selectedPath=[];
let learnSelected=new Set();
let activePdf=null, pdfWords=[], pdfSelected=new Set();
const toast=(m)=>{const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),2200)};
const save=()=>{localStorage.setItem('vf_custom_topics',JSON.stringify(customTopics));localStorage.setItem('vf_learning',JSON.stringify(learning))};
const allTopics=()=>[...BUILTIN,...customTopics];
function dedupe(words){const m=new Map();for(const w of words||[]){if(!w?.en)continue;const k=uid(w);if(!m.has(k))m.set(k,w)}return [...m.values()]}
function collectWords(node,out=[]){out.push(...(node.words||[]));for(const c of node.children||[])collectWords(c,out);return out}
function findNode(path){let nodes=allTopics(),cur=null;for(const p of path){cur=nodes.find(x=>x.name===p);if(!cur)return null;nodes=cur.children||[]}return cur}
function countNode(n){return dedupe(collectWords(n,[])).length}
function currentWords(){return selectedPath.length?dedupe(collectWords(findNode(selectedPath)||{},[])):dedupe(allTopics().flatMap(n=>collectWords(n,[])))}
function addWords(words){const have=new Set(learning.map(uid));let n=0;for(const w of dedupe(words)){if(!have.has(uid(w))){learning.push({...w});have.add(uid(w));n++}}save();renderWords();renderLearning();toast(n?`${n} Wörter hinzugefügt`:'Alle Wörter sind bereits gespeichert')}
function switchView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('#mainNav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='words')renderLearning();if(name==='pdf')renderPdfLibrary();if(name==='grammar')renderGrammar();}
$$('#mainNav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));

function renderTree(){const root=$('#topicTree');root.innerHTML='';const q=$('#topicSearch').value.trim().toLowerCase();function hasMatch(n){return n.name.toLowerCase().includes(q)||(n.children||[]).some(hasMatch)}function el(n,path){if(q&&!hasMatch(n))return null;const wrap=document.createElement('div');wrap.className='topic';const has=(n.children||[]).length;wrap.innerHTML=`<div class="topic-row"><button class="fold">${has?'▾':'·'}</button><button class="name ${JSON.stringify(path)===JSON.stringify(selectedPath)?'active':''}">${esc(n.name)} <span class="count">${countNode(n)}</span></button><button class="plus" title="Ganzes Thema hinzufügen">＋ Alle</button></div>`;wrap.querySelector('.name').onclick=()=>{selectedPath=path;renderTopics()};wrap.querySelector('.plus').onclick=e=>{e.stopPropagation();addWords(collectWords(n,[]))};if(has){const ch=document.createElement('div');ch.className='children';for(const c of n.children){const ce=el(c,[...path,c.name]);if(ce)ch.appendChild(ce)}wrap.appendChild(ch);wrap.querySelector('.fold').onclick=()=>wrap.classList.toggle('collapsed')}return wrap}for(const n of allTopics()){const x=el(n,[n.name]);if(x)root.appendChild(x)}}
function renderTopics(){renderTree();const n=selectedPath.length?findNode(selectedPath):null;$('#topicTitle').textContent=n?n.name:'Alle Themen';$('#crumb').textContent=selectedPath.length?selectedPath.join(' › '):'Themen';const words=currentWords();$('#topicSubtitle').textContent=`${words.length.toLocaleString('de-DE')} unterschiedliche Wörter · einfache Grundlagen bis C2/Native und Fachsprache`;
 const sub=$('#subcats');sub.innerHTML='';const children=n?(n.children||[]):allTopics();for(const c of children){const card=document.createElement('div');card.className='card';const cw=dedupe(collectWords(c,[]));card.innerHTML=`<h3>${esc(c.name)}</h3><p class="muted">${cw.length.toLocaleString('de-DE')} Wörter · ${(c.children||[]).length} Unterkategorien</p><div class="actions"><button class="btn open">Öffnen</button><button class="btn primary add">＋ Alle</button></div>`;card.querySelector('.open').onclick=()=>{selectedPath=[...selectedPath,c.name];renderTopics()};card.querySelector('.add').onclick=()=>addWords(cw);sub.appendChild(card)}renderWords();fillParentSelect();}
function filteredWords(){let w=currentWords();const q=$('#wordSearch').value.trim().toLowerCase(),lvl=$('#levelFilter').value,have=new Set(learning.map(uid));if(q)w=w.filter(x=>(x.en+' '+x.de).toLowerCase().includes(q));if(lvl)w=w.filter(x=>x.level===lvl);if($('#missingOnly').checked)w=w.filter(x=>!have.has(uid(x)));return w}
function renderWords(){const box=$('#wordTable'),words=filteredWords(),have=new Set(learning.map(uid));box.innerHTML='<div class="wrow head"><div>#</div><div>Englisch</div><div>Deutsch</div><div>Level</div><div>Aktion</div></div>';if(!words.length){box.innerHTML+='<div class="empty">Keine passenden Wörter.</div>';return}const f=document.createDocumentFragment();words.slice(0,5000).forEach((w,i)=>{const r=document.createElement('div');r.className='wrow';const added=have.has(uid(w));r.innerHTML=`<div>${i+1}</div><div class="en">${esc(w.en)}</div><div class="de">${esc(w.de)}</div><div><span class="badge ${w.level||''}">${w.level==='C2'?'C2★':esc(w.level||'—')}</span></div><div><button class="btn ${added?'':'primary'}">${added?'✓ gespeichert':'＋ Liste'}</button></div>`;r.querySelector('button').onclick=()=>{if(added){learning=learning.filter(x=>uid(x)!==uid(w));save();renderWords();renderLearning()}else addWords([w])};f.appendChild(r)});box.appendChild(f)}
$('#topicSearch').oninput=renderTree;$('#wordSearch').oninput=renderWords;$('#levelFilter').onchange=renderWords;$('#missingOnly').onchange=renderWords;$('#addAllTopic').onclick=()=>addWords(filteredWords());

function renderLearning(){const q=$('#learnSearch').value.trim().toLowerCase();const rows=learning.map((w,i)=>({w,i})).filter(x=>!q||(x.w.en+' '+x.w.de).toLowerCase().includes(q));const box=$('#learningTable');box.innerHTML='<div class="wrow head"><div></div><div>Englisch</div><div>Deutsch</div><div>Level</div><div>Auswahl</div></div>';if(!rows.length){box.innerHTML+='<div class="empty">Noch keine Wörter gespeichert.</div>';updateLearnSelectionInfo();return}const f=document.createDocumentFragment();for(const {w,i} of rows){const key=uid(w);const r=document.createElement('div');r.className='wrow';r.innerHTML=`<div><input class="check" type="checkbox" ${learnSelected.has(key)?'checked':''}></div><div class="en">${esc(w.en)}</div><div class="de">${esc(w.de)}</div><div><span class="badge ${w.level||''}">${w.level==='C2'?'C2★':esc(w.level||'—')}</span></div><div><button class="btn danger">Löschen</button></div>`;r.querySelector('input').onchange=e=>{e.target.checked?learnSelected.add(key):learnSelected.delete(key);updateLearnSelectionInfo()};r.querySelector('button').onclick=()=>{learning.splice(i,1);learnSelected.delete(key);save();renderLearning();renderWords()};f.appendChild(r)}box.appendChild(f);updateLearnSelectionInfo()}
function updateLearnSelectionInfo(){$('#learnSelectionInfo').textContent=`${learnSelected.size} markiert · ${learning.length} gespeichert`}
$('#learnSearch').oninput=renderLearning;$('#selectAllLearn').onclick=()=>{const q=$('#learnSearch').value.trim().toLowerCase();for(const w of learning)if(!q||(w.en+' '+w.de).toLowerCase().includes(q))learnSelected.add(uid(w));renderLearning()};$('#deleteSelectedLearn').onclick=()=>{if(!learnSelected.size)return toast('Keine Wörter markiert');if(confirm(`${learnSelected.size} markierte Wörter löschen?`)){learning=learning.filter(w=>!learnSelected.has(uid(w)));learnSelected.clear();save();renderLearning();renderWords();toast('Markierte Wörter gelöscht')}};$('#deleteAllLearn').onclick=()=>{if(learning.length&&confirm(`Wirklich alle ${learning.length} Wörter löschen?`)){learning=[];learnSelected.clear();save();renderLearning();renderWords();toast('Lernliste geleert')}};$('#exportLearn').onclick=()=>{const csv='English,Deutsch,Level\n'+learning.map(w=>[w.en,w.de,w.level].map(x=>'"'+String(x||'').replaceAll('"','""')+'"').join(',')).join('\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'vocabfast-meine-woerter.csv')};
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

// IndexedDB PDF library
const DB_NAME='vocabfast_db', STORE='pdfs';
function db(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE,{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function idbAll(){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(STORE).objectStore(STORE).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function idbPut(x){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(STORE,'readwrite').objectStore(STORE).put(x);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function idbDel(id){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(STORE,'readwrite').objectStore(STORE).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function idbClear(){const d=await db();return new Promise((res,rej)=>{const r=d.transaction(STORE,'readwrite').objectStore(STORE).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function renderPdfLibrary(){const list=await idbAll();const box=$('#pdfLibrary');box.innerHTML='';if(!list.length){box.innerHTML='<div class="empty">Noch keine PDFs gespeichert. Hochgeladene PDFs bleiben hier dauerhaft erhalten, solange Browserdaten nicht gelöscht werden.</div>';return}list.sort((a,b)=>b.created-a.created);for(const p of list){const card=document.createElement('div');card.className='pdf-card';card.innerHTML=`<input class="check pdfselect" type="checkbox" data-id="${esc(p.id)}"><div class="pdf-icon">PDF</div><div><h3>${esc(p.name)}</h3><div class="muted">${new Date(p.created).toLocaleString('de-DE')} · ${(p.size/1024/1024).toFixed(1)} MB${p.context?' · '+esc(p.context):''}</div></div><div class="actions"><button class="btn analyze">Wörter anzeigen</button><button class="btn danger del">Löschen</button></div>`;card.querySelector('.analyze').onclick=()=>analyzePdf(p);card.querySelector('.del').onclick=async()=>{if(confirm(`„${p.name}“ löschen?`)){await idbDel(p.id);if(activePdf?.id===p.id)closeAnalysis();renderPdfLibrary();toast('PDF gelöscht')}};box.appendChild(card)}}
$('#pdfInput').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;const ctx=$('#pdfContext').value.trim();for(const file of files){await idbPut({id:crypto.randomUUID(),name:file.name,size:file.size,created:Date.now(),context:ctx,blob:file})}e.target.value='';await renderPdfLibrary();toast(`${files.length} PDF${files.length===1?'':'s'} gespeichert`)};
$('#deleteSelectedPdf').onclick=async()=>{const ids=$$('.pdfselect:checked').map(x=>x.dataset.id);if(!ids.length)return toast('Keine PDFs markiert');if(confirm(`${ids.length} markierte PDFs löschen?`)){for(const id of ids)await idbDel(id);closeAnalysis();await renderPdfLibrary();toast('Markierte PDFs gelöscht')}};
$('#deleteAllPdf').onclick=async()=>{const list=await idbAll();if(list.length&&confirm(`Wirklich alle ${list.length} gespeicherten PDFs löschen?`)){await idbClear();closeAnalysis();renderPdfLibrary();toast('PDF-Bibliothek geleert')}};
const STOP=new Set(('the a an and or but if then than to of in on at by for from with without into onto as is are was were be been being have has had do does did can could may might must shall should will would not no yes this that these those it its they them their we our you your he him his she her i me my mine who whom whose which what when where why how there here all any some each every both either neither more most less least many much few several other another same own such only also very too so just about above below before after during while until between among across through per via section figure table page chapter appendix note notes warning caution procedure procedures shall').split(/\s+/));
async function loadPdfJs(){if(window._pdfjs)return window._pdfjs;const mod=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');mod.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';window._pdfjs=mod;return mod}
async function analyzePdf(p){activePdf=p;$('#pdfAnalysis').classList.remove('hidden');$('#analysisTitle').textContent=p.name;$('#analysisStatus').textContent='PDF wird gelesen …';pdfSelected.clear();pdfWords=[];renderPdfWords();try{const pdfjs=await loadPdfJs();const buf=await p.blob.arrayBuffer();const doc=await pdfjs.getDocument({data:buf}).promise;let text='';for(let i=1;i<=doc.numPages;i++){const pg=await doc.getPage(i),ct=await pg.getTextContent();text+=' '+ct.items.map(x=>x.str).join(' ');$('#analysisStatus').textContent=`Seite ${i}/${doc.numPages} gelesen …`}const counts=new Map();for(const raw of text.match(/[A-Za-z][A-Za-z'-]{1,40}/g)||[]){const w=raw.toLowerCase().replace(/^['-]+|['-]+$/g,'');if(w.length<2||STOP.has(w)||/^\d/.test(w))continue;counts.set(w,(counts.get(w)||0)+1)}pdfWords=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,2500).map(([word,count])=>({word,count}));$('#analysisStatus').textContent=`${pdfWords.length.toLocaleString('de-DE')} unterschiedliche relevante englische Wörter erkannt. Anklicken zum Markieren.`;renderPdfWords();$('#pdfAnalysis').scrollIntoView({behavior:'smooth',block:'start'})}catch(err){console.error(err);$('#analysisStatus').textContent='PDF konnte nicht gelesen werden. Text-PDFs funktionieren direkt; bei Scan-PDFs ist OCR nötig.'}}
function visiblePdfWords(){const q=$('#pdfWordSearch').value.trim().toLowerCase();return q?pdfWords.filter(x=>x.word.includes(q)):pdfWords}
function renderPdfWords(){const box=$('#pdfWordCloud');const scroll=box.scrollTop;box.innerHTML='';for(const x of visiblePdfWords()){const b=document.createElement('button');b.className='chip'+(pdfSelected.has(x.word)?' selected':'');b.innerHTML=`<b>${esc(x.word)}</b> <small>${x.count}×</small>`;b.onclick=()=>{if(pdfSelected.has(x.word)){pdfSelected.delete(x.word);b.classList.remove('selected')}else{pdfSelected.add(x.word);b.classList.add('selected')}updatePdfAddButton();/* intentionally no rerender: scroll position remains exactly where it is */};box.appendChild(b)}box.scrollTop=scroll;updatePdfAddButton()}
function updatePdfAddButton(){$('#addPdfWords').textContent=`${pdfSelected.size} Wörter hinzufügen`}
$('#pdfWordSearch').oninput=renderPdfWords;$('#selectVisiblePdfWords').onclick=()=>{for(const x of visiblePdfWords())pdfSelected.add(x.word);renderPdfWords()};$('#clearPdfWordSelection').onclick=()=>{pdfSelected.clear();renderPdfWords()};$('#addPdfWords').onclick=()=>{const trans=new Map();for(const n of allTopics())for(const w of collectWords(n,[]))if(!trans.has(w.en.toLowerCase()))trans.set(w.en.toLowerCase(),w);const add=[...pdfSelected].map(en=>trans.get(en)||{en,de:'(aus PDF – Übersetzung ergänzen)',level:'—'});addWords(add);pdfSelected.clear();renderPdfWords()};function closeAnalysis(){$('#pdfAnalysis').classList.add('hidden');activePdf=null;pdfWords=[];pdfSelected.clear()}$('#closeAnalysis').onclick=closeAnalysis;

const GRAMMAR=[
{level:'A1',title:'Present Simple',rule:'Für Gewohnheiten, Fakten und regelmäßige Handlungen. He/she/it erhält meist -s.',q:[['She ___ every morning.','runs',['run','runs','running'],'Bei he/she/it steht im Present Simple -s.'],['They ___ in Berlin.','live',['lives','live','living'],'Bei they wird die Grundform verwendet.']]},
{level:'A1',title:'Present Continuous',rule:'am/is/are + Verb-ing für Handlungen, die gerade stattfinden.',q:[['I ___ a checklist right now.','am reading',['read','am reading','reads'],'Right now signalisiert eine laufende Handlung.']]},
{level:'A2',title:'Past Simple & Present Perfect',rule:'Past Simple: abgeschlossene Zeit. Present Perfect: Bezug zur Gegenwart oder unspezifische Zeit.',q:[['I ___ the manual yesterday.','read',['have read','read','am reading'],'Yesterday verlangt Past Simple.'],['I ___ this procedure before.','have seen',['saw','have seen','see'],'Before ohne konkrete vergangene Zeit passt zum Present Perfect.']]},
{level:'B1',title:'Conditionals',rule:'Zero: fact. First: real future. Second: hypothetical. Third: unreal past.',q:[['If the weather improves, we ___ depart.','will',['would','will','would have'],'First conditional: if + present, will + infinitive.'],['If I had known, I ___ differently.','would have acted',['will act','would act','would have acted'],'Third conditional beschreibt eine irreale Vergangenheit.']]},
{level:'B1',title:'Passive Voice',rule:'be + past participle. Wichtig in technischen Handbüchern und Verfahren.',q:[['The filter ___ every 100 hours.','is replaced',['replaces','is replaced','has replacing'],'Das Objekt steht im Fokus: Passive Voice.']]},
{level:'B2',title:'Modal verbs & deduction',rule:'must = starke Schlussfolgerung; might/could = Möglichkeit; can’t = nahezu unmöglich.',q:[['The gauge is at zero; the sensor ___ be faulty.','might',['must to','might','is might'],'Modalverb + Grundform ohne to.']]},
{level:'B2',title:'Reported Speech',rule:'Bei zurückliegendem reporting verb erfolgt häufig backshift: present → past, will → would.',q:[['He said that the system ___ operational.','was',['is','was','will'],'Nach said wird häufig zurückgestuft.']]},
{level:'C1',title:'Inversion for emphasis',rule:'Nach negativen/limitierenden Adverbialen folgt Inversion: Never have I…, Only then did we…',q:[['Rarely ___ such severe turbulence.','have I encountered',['I have encountered','have I encountered','I encountered'],'Rarely am Satzanfang löst subject–auxiliary inversion aus.'],['Only after landing ___ the fault.','did we discover',['we discovered','did we discover','we did discovered'],'Only after + fronted phrase verlangt Inversion im Hauptsatz.']]},
{level:'C1',title:'Cleft sentences',rule:'It-clefts und wh-clefts heben Information hervor: It was X that… / What matters is…',q:[['It was the tail rotor ___ caused the vibration.','that',['what','that','where'],'Ein it-cleft verwendet hier that/who.']]},
{level:'C2',title:'Subjunctive & mandative structures',rule:'In formeller Sprache nach demand/recommend/essential: that + Grundform, auch bei he/she/it.',q:[['The inspector recommended that the part ___ immediately.','be replaced',['is replaced','be replaced','was replaced'],'Mandative subjunctive: Grundform be.']]},
{level:'C2',title:'Advanced participle clauses',rule:'Perfect participle: Having + past participle zeigt Vorzeitigkeit. Passive: Having been + past participle.',q:[['___ the discrepancy, the crew delayed departure.','Having identified',['Identifying had','Having identified','Have identified'],'Die Identifikation geschah vor der Verzögerung.']]},
{level:'C2',title:'Hedging & epistemic precision',rule:'Akademisches und professionelles Englisch nutzt hedging: appears to, is likely to, may well, arguably.',q:[['The evidence ___ suggest a transient electrical fault.','appears to',['appears','appears to','is appear to'],'appear to + infinitive formuliert eine vorsichtige Schlussfolgerung.']]}
];
function renderGrammar(){const lvl=$('#grammarLevel').value;const box=$('#grammarTopics');box.innerHTML='';for(const g of GRAMMAR.filter(x=>!lvl||x.level===lvl)){const c=document.createElement('div');c.className='card';c.innerHTML=`<h3>${g.level} · ${esc(g.title)}</h3><p class="grammar-rule muted">${esc(g.rule)}</p><button class="btn practice">Üben</button>`;c.querySelector('.practice').onclick=()=>makeGrammarQuiz(g.q.map(q=>({...{level:g.level,title:g.title},q})));box.appendChild(c)}}
function allQuestions(){return GRAMMAR.flatMap(g=>g.q.map(q=>({level:g.level,title:g.title,q})))}
function makeGrammarQuiz(items){let pool=items?.length?items:allQuestions().filter(x=>!$('#grammarLevel').value||x.level===$('#grammarLevel').value);pool=[...pool].sort(()=>Math.random()-.5).slice(0,10);const box=$('#grammarQuiz');box.innerHTML='';pool.forEach((x,i)=>{const [text,answer,opts,why]=x.q;const q=document.createElement('div');q.className='question';q.innerHTML=`<h3>${i+1}. ${esc(text)}</h3><div class="muted">${x.level} · ${esc(x.title)}</div><div class="options"></div><div class="explain"></div>`;const ob=q.querySelector('.options');for(const op of [...opts].sort(()=>Math.random()-.5)){const b=document.createElement('button');b.className='btn option';b.textContent=op;b.onclick=()=>{[...ob.children].forEach(z=>z.disabled=true);b.classList.add(op===answer?'correct':'wrong');if(op!==answer)[...ob.children].find(z=>z.textContent===answer)?.classList.add('correct');q.querySelector('.explain').textContent=why};ob.appendChild(b)}box.appendChild(q)})}
$('#grammarLevel').onchange=renderGrammar;$('#newGrammarQuiz').onclick=()=>makeGrammarQuiz();

function topicPaths(){const out=[[]];function walk(n,p){const path=[...p,n.name];out.push(path);for(const c of n.children||[])walk(c,path)}for(const n of allTopics())walk(n,[]);return out}
function fillParentSelect(){const s=$('#customParent');const val=s.value;s.innerHTML='<option value="[]">Oberste Ebene</option>'+topicPaths().slice(1).map(p=>`<option value='${esc(JSON.stringify(p))}'>${esc(p.join(' › '))}</option>`).join('');if([...s.options].some(o=>o.value===val))s.value=val}
$('#newTopic').onclick=()=>{$('#topicDialog').showModal();fillParentSelect()};
function parseCustom(){return $('#customTopicWords').value.split(/\n+/).map(line=>{const m=line.match(/^\s*(.*?)\s*=\s*(.*?)(?:\s*\|\s*(A1|A2|B1|B2|C1|C2))?\s*$/i);return m?{en:m[1].trim(),de:m[2].trim(),level:(m[3]||'B2').toUpperCase()}:null}).filter(Boolean)}
function keywordWords(name,parent){const text=(name+' '+parent.join(' ')).toLowerCase();const tokens=text.split(/[^a-zäöüß]+/).filter(x=>x.length>2);let scored=[];function walk(n,path=[]){const hay=(path.join(' ')+' '+n.name).toLowerCase();let score=tokens.reduce((a,t)=>a+(hay.includes(t)?2:0),0);if(score)scored.push([score,n]);for(const c of n.children||[])walk(c,[...path,n.name])}for(const n of BUILTIN)walk(n);scored.sort((a,b)=>b[0]-a[0]);let words=[];for(const [,n] of scored.slice(0,8))words.push(...collectWords(n,[]));if(words.length<250)words.push(...currentWords().filter(w=>w.level==='C1'||w.level==='C2').slice(0,500));return dedupe(words).slice(0,900)}
$('#autoGenerateTopic').onclick=()=>{const name=$('#customTopicName').value.trim();if(!name)return toast('Bitte zuerst einen Themennamen eingeben');const parent=JSON.parse($('#customParent').value||'[]');const w=keywordWords(name,parent);$('#customTopicWords').value=w.map(x=>`${x.en} = ${x.de} | ${x.level||'B2'}`).join('\n');toast(`${w.length} passende Wörter vorbereitet`)};
function insertNode(parent,node){if(!parent.length){customTopics.push(node);return}let roots=allTopics(),cur=null;for(const p of parent){cur=roots.find(n=>n.name===p);if(!cur)break;roots=cur.children||[]}if(cur){cur.children=cur.children||[];cur.children.push(node);if(!cur.custom){ // builtins are in-memory; persist insertion as mirrored custom branch
  // store as top-level custom path container if parent is builtin
  let root=customTopics.find(x=>x.name===parent[0]&&x._overlay);if(!root){root={name:parent[0],words:[],children:[],custom:true,_overlay:true};customTopics.push(root)}
  let c=root;for(const p of parent.slice(1)){let n=c.children.find(x=>x.name===p);if(!n){n={name:p,words:[],children:[],custom:true,_overlay:true};c.children.push(n)}c=n}c.children.push(node)
 }}else customTopics.push(node)}
$('#saveCustomTopic').onclick=()=>{const name=$('#customTopicName').value.trim();if(!name)return toast('Themenname fehlt');const parent=JSON.parse($('#customParent').value||'[]');const words=dedupe(parseCustom());const node={name,words,children:[],custom:true};insertNode(parent,node);save();$('#topicDialog').close();$('#customTopicName').value='';$('#customTopicWords').value='';selectedPath=[];renderTopics();toast(`Thema „${name}“ gespeichert`)};

$('#profileName').value=localStorage.getItem('vf_profile_name')||'';$('#saveProfile').onclick=()=>{localStorage.setItem('vf_profile_name',$('#profileName').value.trim());toast('Profil gespeichert')};
$('#deleteAccount').onclick=async()=>{const phrase=prompt('Zum endgültigen Löschen aller lokalen Daten bitte LÖSCHEN eingeben:');if(phrase!=='LÖSCHEN')return;localStorage.removeItem('vf_custom_topics');localStorage.removeItem('vf_learning');localStorage.removeItem('vf_profile_name');await idbClear();customTopics=[];learning=[];learnSelected.clear();$('#profileName').value='';selectedPath=[];renderTopics();renderLearning();renderPdfLibrary();toast('Alle lokalen Kontodaten wurden gelöscht')};

renderTopics();renderLearning();renderPdfLibrary();renderGrammar();
})();
